JOIN system.roles role ON role.tenant_id IS NULL AND role.role_key = seed.role_key
JOIN system.permissions permission ON permission.permission_key = seed.permission_key
ORDER BY seed.role_key, seed.permission_key;

INSERT INTO system.role_conflicts (role_id_low, role_id_high, reason)
SELECT LEAST(low_role.id, high_role.id), GREATEST(low_role.id, high_role.id),
       'platform_three_administrators_separation_of_duties'
FROM (VALUES
    ('platform.audit_administrator', 'platform.security_administrator'),
    ('platform.audit_administrator', 'platform.system_administrator'),
    ('platform.security_administrator', 'platform.system_administrator')
) AS seed(low_role_key, high_role_key)
JOIN system.roles low_role ON low_role.tenant_id IS NULL AND low_role.role_key = seed.low_role_key
JOIN system.roles high_role ON high_role.tenant_id IS NULL AND high_role.role_key = seed.high_role_key
ORDER BY seed.low_role_key, seed.high_role_key;

